<template><view class="page"><view class="row-between"><view class="page-title">发现活动</view><view class="row"><button size="mini" @click="invite">邀请码</button><button size="mini" class="mini-primary" @click="create">发布</button></view></view><ActivityCard v-for="item in list" :key="item.id" :activity="item" @open="open" /><view v-if="!loading&&!list.length" class="empty">暂无公开活动</view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import ActivityCard from'@/components/ActivityCard.vue';import{api}from'@/services/api';import{requireSession}from'@/services/session';import type{Activity,PageData}from'@/services/types';const list=ref<Activity[]>([]),loading=ref(false);onShow(async()=>{if(!requireSession())return;loading.value=true;try{list.value=(await api<PageData<Activity>>('/activities?scope=discover&size=50')).items}finally{loading.value=false}});const open=(id:number)=>uni.navigateTo({url:`/pages/activityDetail/activityDetail?id=${id}`});const create=()=>uni.navigateTo({url:'/pages/activityCreate/activityCreate'});const invite=()=>uni.navigateTo({url:'/pages/invite/invite'})</script>
